//! Clocky desktop app: floating dock with the radial menu, panels, manage window and tray.
// Without this, Windows opens a console next to the app.
#![cfg_attr(windows, windows_subsystem = "windows")]

/// Code generated by Slint from `ui/`.
///
/// The generated code does not pass the workspace's clippy lints, so they are allowed only here.
#[allow(clippy::all, clippy::pedantic, clippy::restriction)]
mod ui {
    slint::include_modules!();
}

mod app;
mod bridge;
mod chips;
mod command;
mod core;
mod demo;
mod dock;
mod format;
mod geometry;
mod instance;
mod log;
mod manage;
mod manage_view;
mod notify;
mod palette;
mod panel;
mod paths;
mod picker;
mod picker_ui;
mod screenshot;
mod settings;
mod sound;
mod startup;
mod tour;
mod tray;

fn main() {
    let log_file = log::init(&paths::log_dir()).ok();
    tracing::info!(
        "starting Clocky {} (log: {log_file:?})",
        clocky_core::version()
    );
    match run() {
        Ok(()) => tracing::info!("exiting"),
        Err(e) => {
            tracing::error!("fatal error: {e:#}");
            std::process::exit(1);
        }
    }
}

fn run() -> anyhow::Result<()> {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let launch = command::parse_args(&args)?;
    let screenshot_dir = screenshot::dir_from_env();
    // Screenshot runs are independent of a running Clocky.
    if screenshot_dir.is_none() {
        if instance::forward(launch.command()) {
            tracing::info!("Clocky is already running: sent {:?}", launch.command());
            return Ok(());
        }
        if let command::Launch::Send(command) = launch {
            anyhow::bail!("no running Clocky to receive {command:?}");
        }
    }
    select_backend()?;
    let mut core = match startup::open_core() {
        Ok(core) => core,
        Err(failure) => {
            tracing::error!(
                "cannot open the database {}: {}",
                failure.path,
                failure.message
            );
            startup::show_failure(&failure, screenshot_dir)?;
            anyhow::bail!("the database could not be opened");
        }
    };
    // Listen before creating the windows: that can take seconds on a cold start, and a launch
    // during it must reach this instance instead of starting a second one.
    if screenshot_dir.is_none() {
        instance::listen(app::run_command)?;
    }
    if demo::requested() {
        match demo::seed_if_empty(&mut core, &chrono::Local) {
            Ok(seeded) => tracing::info!("demo data requested (seeded: {seeded})"),
            Err(e) => tracing::warn!("failed to seed the demo data: {e}"),
        }
    }
    let app = app::App::new(core, screenshot_dir.is_some())?;
    app.start()?;
    if let Some(dir) = screenshot_dir {
        app.schedule_screenshots(dir);
    }
    // The app lives in the tray: closing every window does not end it, only "Sair" does.
    slint::run_event_loop_until_quit()?;
    Ok(())
}

/// Selects the winit backend (the dock relies on winit window APIs).
fn select_backend() -> anyhow::Result<()> {
    let selector = slint::BackendSelector::new().backend_name("winit".into());
    #[cfg(all(unix, not(target_vendor = "apple")))]
    let selector = selector.with_winit_event_loop_builder(linux_event_loop_builder());
    selector.select()?;
    Ok(())
}

/// Wayland does not let an app place its own windows, and the dock must sit at a screen edge.
/// So on Linux the app goes through X11 (XWayland on Wayland desktops) whenever `DISPLAY` is set.
#[cfg(all(unix, not(target_vendor = "apple")))]
fn linux_event_loop_builder() -> slint::winit_030::EventLoopBuilder {
    use slint::winit_030::winit::platform::x11::EventLoopBuilderExtX11;
    let mut builder =
        slint::winit_030::winit::event_loop::EventLoop::<slint::winit_030::SlintEvent>::with_user_event();
    if std::env::var_os("DISPLAY").is_some() {
        builder.with_x11();
    }
    builder
}
